const key='pumpkin-night-fair-v1',fmt=n=>n.toLocaleString(lang==='ro'?'ro-RO':'en-US',{maximumFractionDigits:2}),from=p=>unit==='kg'?p/LB:unit==='g'?p/LB*1000:p;
