try{const data=JSON.parse(localStorage.getItem(key));if(data&&Array.isArray(data.entries)){entries=data.entries.filter(e=>e&&Number.isFinite(e.pounds)&&e.pounds>=0&&Number.isFinite(e.time)).slice(0,20);sessionBest=Math.max(0,...entries.map(e=>e.pounds),Number.isFinite(data.best)&&data.best>=0?data.best:0);}}catch{}
