function fraction(p){p=Math.min(4000,Math.max(0,p));for(let i=1;i<stops.length;i++)if(p<=stops[i])return(i-1+(p-stops[i-1])/(stops[i]-stops[i-1]))/6;return 1;}
function inverse(f){const x=Math.min(1,Math.max(0,f))*6,i=Math.min(5,Math.floor(x));return stops[i]+(x-i)*(stops[i+1]-stops[i]);}
