$('#motion').onclick=()=>{const reduced=document.documentElement.dataset.motion!=='reduce';document.documentElement.dataset.motion=reduced?'reduce':'auto';$('#motion').setAttribute('aria-pressed',String(reduced));};
$('#water').onclick=()=>{nudge(unit==='kg'?5:unit==='g'?5000:10);effect('.rain',9,'💧');$('.scene').classList.remove('watering');void $('.scene').offsetWidth;$('.scene').classList.add('watering');};
$('#weigh').onclick=()=>{if(weighPumpkin(pounds)===INVALID_WEIGHT){$('#status').textContent=text('Greutate invalidă. Rezultatul nu a fost înscris.','Invalid weight. No entry was recorded.');$('#weight').focus();return;}entries.unshift({pounds,time:Date.now()});entries=entries.slice(0,1000);sessionBest=Math.max(sessionBest,pounds);const persisted=save();ledger();$('#status').textContent=persisted?text('Dovleac înscris în registru!','Pumpkin added to the ledger!'):text('Înscris pentru această sesiune; salvarea nu este disponibilă.','Added for this session; saving is unavailable.');$('#stamp').textContent=weighPumpkin(pounds);$('#stamp').classList.remove('pop');void $('#stamp').offsetWidth;$('#stamp').classList.add('pop');if(pounds>=1000)effect('.confetti',30,'');};
