const names=['Gourd','Jack','Monster','Beast'];[4,22,310,1247].forEach((p,i)=>{const b=document.createElement('button');b.dataset.preset=p;b.innerHTML=`<svg viewBox="0 0 40 36" aria-hidden="true"><ellipse cx="12" cy="22" rx="9" ry="11" fill="#e87825"/><ellipse cx="28" cy="22" rx="9" ry="11" fill="#e87825"/><ellipse cx="20" cy="22" rx="10" ry="12" fill="#ffad51"/><path d="M20 11q-5-8 2-9" stroke="#7eae68" stroke-width="4" fill="none"/></svg><b>${names[i]}</b><small></small>`;b.onclick=()=>setPounds(p);$('#presets').append(b);});
CATEGORY_NAMES.forEach((name,i)=>{const li=document.createElement('li');li.dataset.tierIndex=i;const b=document.createElement('strong'),s=document.createElement('small');b.textContent=name;s.textContent=i===5?'≥ 2749 lb':`${stops[i]} ≤ lb < ${stops[i+1]}`;li.append(b,s);$('#tiers').append(li);const angle=t=>Math.PI-Math.PI*t/6;const x=t=>100+80*Math.cos(angle(t)),y=t=>100-80*Math.sin(angle(t));const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M${x(i)} ${y(i)} A80 80 0 0 1 ${x(i+1)} ${y(i+1)}`);path.setAttribute('fill','none');path.setAttribute('stroke',colors[i]);path.setAttribute('stroke-width','12');$('#bands').append(path);});
