// Night Fair Studio. Concatenated after app.js; uses its canonical pound state.
let svgSequence=0;
let settings={...DEFAULT_SETTINGS},design=normalizeDesign(),gallery=[],progress={xp:0,games:0,categories:[],daily:[],scores:[]};
let selectedEntries=new Set(),undoDeletion=null,designUndo=[],designRedo=[],audio=null,ambientOsc=null,ambientGain=null,installEvent=null,storageAvailable=true;
const extKey='pumpkin-night-fair-studio-v2',copy=v=>JSON.parse(JSON.stringify(v)),uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
let activePage='scale';
function notify(ro,en){$('#global-status').textContent=text(ro,en);}
function serialize(){return {schema:2,design:copy(design),gallery:copy(gallery),entries:entries.map(e=>({id:e.id||uid(),name:e.name||'Jack',pounds:e.pounds,time:e.time})),progress:copy(progress)};}
function persist(){try{localStorage.setItem(extKey,JSON.stringify({...serialize(),settings,lang,unit}));storageAvailable=true;}catch{storageAvailable=false;notify('Stockarea este indisponibilă sau plină. Descarcă un backup JSON.','Storage is unavailable or full. Download a JSON backup.');}}
try{const raw=JSON.parse(localStorage.getItem(extKey));if(raw){const state=validateBackup(raw);({design,gallery,entries,progress}=state);settings={...DEFAULT_SETTINGS};for(const k of Object.keys(DEFAULT_SETTINGS)){if(typeof raw.settings?.[k]===typeof DEFAULT_SETTINGS[k])settings[k]=raw.settings[k];}if(raw.lang==='en')lang='en';if(['lb','kg','g'].includes(raw.unit))unit=raw.unit;}}catch{notify('Datele vechi nu au fost încărcate. Poți importa un backup valid.','Previous data could not be loaded. You can import a valid backup.');}
entries=entries.map(e=>({...e,id:e.id||uid(),name:e.name||'Jack'}));
function go(page,focus=true){activePage=page;document.querySelectorAll('.page').forEach(e=>e.hidden=e.id!==`page-${page}`);document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.page===page)));if(focus){const h=$(`#page-${page} h2`);h?.setAttribute('tabindex','-1');h?.focus({preventScroll:true});}stop();if(page==='collection')collection();if(page==='studio'){syncDesignControls();drawStudio();}}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
function sound(kind='weigh'){
 if(!settings.sound||settings.volume<=0)return;
 try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const frequencies=kind==='water'?[480,650,850]:kind==='error'?[170,120]:kind==='win'?[523,659,784,1046]:kind==='click'?[440]:[262,330,392];frequencies.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.09;o.type='sine';o.frequency.setValueAtTime(hz,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(settings.volume/100*.12,t+.015);g.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+.24);});}catch{notify('Sunetul nu este disponibil în acest browser.','Audio is unavailable in this browser.');}
}
function ambient(){if(ambientOsc){ambientOsc.stop();ambientOsc=null;}if(!settings.ambient||!settings.sound||document.hidden)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();ambientOsc=audio.createOscillator();ambientGain=audio.createGain();ambientOsc.frequency.value=110;ambientGain.gain.value=settings.volume/100*.012;ambientOsc.connect(ambientGain).connect(audio.destination);ambientOsc.start();}catch{}}
const saveBase=save;save=function(){const ok=saveBase();persist();return ok&&storageAvailable;};
const renderBase=render;render=function(opts){renderBase(opts);const valid=Number.isFinite(pounds)&&pounds>=0,i=CATEGORY_NAMES.indexOf(weighPumpkin(pounds));$('#next-tier').textContent=valid?(pounds>4000?text('Peste limita vizuală de 4000 lb. Greutatea și categoria rămân corecte.','Beyond the 4000 lb visual scale. Weight and category remain accurate.'):i<5?`${text('Până la','Until')} ${CATEGORY_NAMES[i+1]}: ${fmt(from(stops[i+1]-pounds))} ${unit}`:text('Ai atins categoria maximă.','You reached the highest category.')):'';$('.scene').dataset.name=design.name;$('#stamp').textContent=valid?weighPumpkin(pounds):'—';const original=$('.pumpkin svg');if(original)original.innerHTML=svgContent(design);document.querySelectorAll('[data-unit]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.unit===unit)));};
const langBase=language;language=function(){langBase();$('#global-status').textContent='';$('#game-result').textContent='';document.querySelectorAll('[data-ro-label]').forEach(e=>e.setAttribute('aria-label',e.dataset[`${lang}Label`]));collection();progressView();syncDesignControls();if(game?.running)drawGame();if($('#guide').open)guideView();persist();};
function progressView(){const level=1+Math.floor(progress.xp/150);$('#xp-strip').textContent=`✦ ${progress.xp} XP · ${text('Nivel','Level')} ${level} · ${progress.categories.length}/6 ${text('categorii','categories')}`;$('#unlock-info').textContent=text('Accesorii bonus: fundă la 150 XP, coroană la 300 XP. Modelele de bază sunt mereu disponibile.','Bonus accessories: bow at 150 XP, crown at 300 XP. Basic designs are always available.');for(const o of $('#hat').options){o.disabled=(o.value==='bow'&&progress.xp<150)||(o.value==='crown'&&progress.xp<300);} }
function reward(xp){progress.xp+=xp;progressView();persist();}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));}
function svgContent(d,weight=pounds){
 const gradient='skin-'+(++svgSequence);
 const transform=d.shape==='wide'?'translate(-15 18) scale(1.15 .88)':d.shape==='tall'?'translate(18 -12) scale(.82 1.08)':'';
 const faces={classic:'<path d="M65 84l21-8 2 20zM135 84l-21-8-2 20zM66 111l14 8 9-5 12 9 12-9 9 5 12-8q-33 43-68 0"/>',cute:'<circle cx="77" cy="88" r="7"/><circle cx="123" cy="88" r="7"/><path d="M85 112q15 20 30 0" fill="none" stroke="currentColor" stroke-width="5"/>',angry:'<path d="M63 76l27 12-24 8zM137 76l-27 12 24 8zM68 119l16-7 15 8 15-8 17 7-15 10-17-5-16 5z"/>',surprised:'<circle cx="77" cy="88" r="9"/><circle cx="123" cy="88" r="9"/><ellipse cx="100" cy="120" rx="10" ry="14"/>',none:''};
 let paths='';for(const s of d.strokes){if(!s.points.length)continue;const path=s.points.map((p,i)=>`${i?'L':'M'}${p[0]} ${p[1]}`).join(' ');paths+=`<path d="${path}" fill="none" stroke="${s.tool==='carve'?(d.light?d.lightColor:'#2b1020'):s.color}" stroke-width="${s.width}" stroke-linecap="round" stroke-linejoin="round"/>`;}
 const automatic=weight<1?'surprised':weight<10?'cute':weight>=1000?'angry':'classic';
 const faceColor=d.light?d.lightColor:'#2b1020',glow=d.light?`<ellipse cx="100" cy="93" rx="85" ry="66" fill="${d.lightColor}" opacity="${d.intensity/500}"/>`:'';
 const hats={none:'',witch:'<path d="M60 42l32-40 30 40z" fill="#50296a"/><ellipse cx="93" cy="42" rx="52" ry="8" fill="#6c3b83"/><path d="M77 25h29" stroke="#ffba64" stroke-width="6"/>',crown:'<path d="M65 43l-5-26 22 14 18-26 18 26 22-14-5 26z" fill="#ffd36b" stroke="#9c6d14"/>',bow:'<path d="M101 39q-48-40-42-2 9 26 42 2 39-35 42-2-6 27-42 2" fill="#e88ab8"/><circle cx="101" cy="39" r="7" fill="#a54d80"/>'};
 return `<defs><radialGradient id="${gradient}" cx="35%" cy="25%" r="80%"><stop offset="0" stop-color="${d.color}"/><stop offset="1" stop-color="${d.color}" stop-opacity=".55"/></radialGradient></defs><ellipse cx="100" cy="159" rx="70" ry="7" fill="#0004"/><g transform="${transform}">${glow}<g fill="url(#${gradient})" stroke="#57232c" stroke-opacity=".4" stroke-width="1.6"><ellipse cx="55" cy="95" rx="30" ry="50"/><ellipse cx="145" cy="95" rx="30" ry="50"/><ellipse cx="78" cy="95" rx="33" ry="55"/><ellipse cx="122" cy="95" rx="33" ry="55"/><ellipse cx="100" cy="95" rx="34" ry="57"/></g><path d="M94 42q-4-20-14-25 20-4 23 10 8-12 16-5-12 8-12 20" fill="#80603d"/><path d="M108 30q25-20 34-2-16 16-34 2" fill="#67934f"/><g fill="${faceColor}" color="${faceColor}" opacity="${d.light?.3+d.intensity/143:1}">${faces[d.face==='auto'?automatic:d.face]}</g>${paths}${d.stickers.map(s=>`<text x="${s.x}" y="${s.y}" text-anchor="middle" font-size="18">${s.text}</text>`).join('')}${d.face==='auto'&&weight>=1000&&d.hat==='none'?'<path d="M58 53L52 23 75 44M142 53L148 23 125 44" fill="#f4ddba"/>':''}${hats[d.hat]}</g>`;
}
function svgDocument(d,weight=pounds){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 170" width="800" height="680">${svgContent(d,weight)}</svg>`;}
function drawStudio(){ $('#studio-svg').innerHTML=svgContent(design);$('#drawing').getContext('2d').clearRect(0,0,800,680);render();}
function snapshot(){designUndo.push(copy(design));if(designUndo.length>30)designUndo.shift();designRedo=[];}
function changed(){drawStudio();persist();}
function syncDesignControls(){for(const [id,k]of [['pumpkin-name','name'],['shape','shape'],['face-select','face'],['hat','hat'],['pumpkin-color','color'],['light-color','lightColor'],['light-intensity','intensity']])$('#'+id).value=design[k];$('#light').checked=design.light;progressView();}
for(const [id,k]of [['pumpkin-name','name'],['shape','shape'],['face-select','face'],['hat','hat'],['pumpkin-color','color'],['light-color','lightColor'],['light-intensity','intensity'],['light','light']])$('#'+id).addEventListener('change',()=>{snapshot();design[k]=k==='light'?$('#'+id).checked:k==='intensity'?Number($('#'+id).value):$('#'+id).value;changed();});
$('#undo-design').onclick=()=>{if(!designUndo.length)return;designRedo.push(copy(design));design=designUndo.pop();syncDesignControls();changed();};$('#redo-design').onclick=()=>{if(!designRedo.length)return;designUndo.push(copy(design));design=designRedo.pop();syncDesignControls();changed();};$('#reset-design').onclick=()=>{snapshot();design=normalizeDesign();syncDesignControls();changed();};
let stroke=null;const canvas=$('#drawing'),ctx=canvas.getContext('2d');
function point(e){const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(200,(e.clientX-r.left)/r.width*200)),Math.max(0,Math.min(170,(e.clientY-r.top)/r.height*170))];}
canvas.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);snapshot();stroke={tool:$('#tool').value,color:$('#paint-color').value,width:Number($('#brush-size').value),points:[point(e)]};};
canvas.onpointermove=e=>{if(!stroke)return;const p=point(e);if(stroke.points.length<1000)stroke.points.push(p);ctx.clearRect(0,0,800,680);ctx.beginPath();for(const [i,q]of stroke.points.entries())i?ctx.lineTo(q[0]*4,q[1]*4):ctx.moveTo(q[0]*4,q[1]*4);ctx.lineWidth=stroke.width*4;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=stroke.tool==='erase'?design.color:stroke.tool==='carve'?'#2b1020':stroke.color;ctx.stroke();};
function finishStroke(){if(!stroke)return;if(stroke.tool==='erase'){const radius=stroke.width,pts=stroke.points;design.strokes=design.strokes.filter(s=>!s.points.some(p=>pts.some(q=>Math.hypot(p[0]-q[0],p[1]-q[1])<radius)));}else{design.strokes.push(stroke);design.strokes=design.strokes.slice(-100);}stroke=null;changed();}
canvas.onpointerup=finishStroke;canvas.onpointercancel=finishStroke;canvas.onlostpointercapture=finishStroke;
$('#pattern').onclick=()=>{snapshot();for(let i=0;i<12;i++){const x=48+(i%4)*34,y=65+Math.floor(i/4)*29;design.strokes.push({tool:'paint',color:$('#paint-color').value,width:8,points:[[x,y],[x+.1,y]]});}design.strokes=design.strokes.slice(-100);changed();};
$('#sticker').onclick=()=>{snapshot();design.stickers.push({text:$('#sticker-type').value,x:Number($('#sticker-x').value),y:Number($('#sticker-y').value)});design.stickers=design.stickers.slice(-25);changed();};
function download(name,blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function saveGallery(){if(!Number.isFinite(pounds)||pounds<0){notify('Introdu o greutate validă.','Enter a valid weight.');return;}if(gallery.length>=60){notify('Galeria are 60 de modele. Exportă un backup și șterge unul pentru a continua.','The gallery has 60 designs. Export a backup and remove one to continue.');return;}gallery.unshift({id:uid(),pounds,time:Date.now(),favorite:false,design:copy(design)});reward(5);persist();collection();notify('Model salvat în galerie.','Design saved to the gallery.');}
$('#save-design').onclick=saveGallery;
