const guideSteps=[['scale','Cântărește','Weigh','Scrie o greutate, alege lb/kg/g sau o presetare. Doar Cântărește adaugă în registru. Pragurile sunt în lb.','Type a weight, select lb/kg/g or a preset. Only Weigh adds an entry. Thresholds are in lb.'],['studio','Creează un felinar','Create a lantern','Alege forma, fața și culoarea. Poți desena, sculpta, adăuga modele sau abțibilduri. Aprinde felinarul, apoi salvează în galerie.','Choose shape, face and color. Draw, carve, add patterns or stickers. Light your lantern and save it to the gallery.'],['play','Joacă și învață','Play and learn','Alege unul dintre cele nouă moduri. Jocurile acordă XP, insigne și accesorii. Pauza oprește timpul; o rundă abandonată nu acordă XP.','Choose one of nine modes. Games grant XP, badges and accessories. Pause stops time; abandoned rounds do not grant XP.'],['collection','Păstrează colecția','Keep your collection','Compară două cântăriri, filtrează registrul și salvează un backup JSON. Importul verifică fișierul înainte de înlocuire.','Compare two weigh-ins, filter the ledger and save a JSON backup. Import validates the file before replacing data.'],['settings','Adaptează experiența','Make it yours','Alege tema, contrastul, mișcarea, sunetul și durata jocurilor. Toate jocurile și salvările sunt locale, fără cont.','Choose theme, contrast, motion, sound and game duration. All games and saves are local, with no account.']];let guideStep=0;
function guideView(){const s=guideSteps[guideStep];$('#guide-title').textContent=`${guideStep+1}/5 · ${text(s[1],s[2])}`;$('#guide-text').textContent=text(s[3],s[4]);$('#guide-back').disabled=guideStep===0;$('#guide-next').disabled=guideStep===4;}
$('#tutorial').onclick=()=>{guideStep=0;guideView();$('#guide').showModal();};$('#guide-back').onclick=()=>{guideStep=Math.max(0,guideStep-1);guideView();};$('#guide-next').onclick=()=>{guideStep=Math.min(4,guideStep+1);guideView();};$('#guide-close').onclick=()=>{const page=guideSteps[guideStep][0];$('#guide').close();go(page);};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;});
