let registration=null;
async function offline(){if(location.protocol==='file:'){$('#offline-status').textContent=text('Fișier complet: merge direct și fără internet. Instalarea PWA necesită versiunea găzduită HTTPS.','Complete file: works directly without internet. PWA installation requires the HTTPS hosted version.');return;}if(!('serviceWorker'in navigator)){$('#offline-status').textContent=text('Acest browser nu acceptă service worker.','This browser does not support service workers.');return;}try{registration=await navigator.serviceWorker.register('./sw.js');$('#offline-status').textContent=text('Offline pregătit după prima încărcare completă.','Offline ready after the first complete load.');registration.addEventListener('updatefound',()=>{const worker=registration.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)notify('Actualizare disponibilă. Folosește Caută actualizări în Setări.','Update available. Use Check for updates in Settings.');});});}catch{$('#offline-status').textContent=text('Offline PWA indisponibil. Fișierul complet poate fi descărcat pentru utilizare locală.','PWA offline is unavailable. Download the complete file for local use.');}}
$('#update-app').onclick=async()=>{if(!registration){notify('Pentru actualizări PWA, deschide versiunea găzduită HTTPS.','For PWA updates, open the HTTPS hosted version.');return;}try{await registration.update();if(registration.waiting){registration.waiting.postMessage('ACTIVATE');notify('Actualizare activată. Reîncarcă pagina după salvarea lucrului.','Update activated. Reload after saving your work.');}else notify('Nu există actualizări în așteptare.','No updates are waiting.');}catch{notify('Verificarea actualizărilor nu a reușit. Încearcă atunci când ai internet.','Update check failed. Try again when online.');}};
