$('#logic-tests').onclick=e=>{e.preventDefault();let dialog=$('#logic-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='logic-dialog';document.body.append(dialog);}dialog.replaceChildren();dialog.append(line(text('Verificări de logică','Logic checks'),'h2'));const cases=[[0,'Tiny Gourd'],[.99,'Tiny Gourd'],[1,'Mini'],[10,'Carving'],[50,'Giant'],[1000,'Record Breaker!'],[2749,'Legendary'],[-5,INVALID_WEIGHT],['heavy',INVALID_WEIGHT],['',INVALID_WEIGHT],[null,INVALID_WEIGHT],[Infinity,INVALID_WEIGHT]];let count=0;for(const [weight,expected]of cases){const ok=weighPumpkin(weight)===expected;count+=Number(ok);dialog.append(line(`${ok?'✓':'✕'} ${String(weight)} → ${weighPumpkin(weight)}`));}dialog.append(line(`${count}/${cases.length} ${text('trecute. Acestea sunt verificări locale, nu raportul oficial CodePen.','passed. These are local checks, not the official CodePen report.')}`),gameButton(text('Închide','Close'),()=>dialog.close()));dialog.showModal();};
